// Copyright 2024 Apheleia
//
// Description:
// Apheleia Verification Library (AVL) Benchmark
//
// Unconstrained randomization - $urandom and $urandom_range.
//
// This file is compiled unchanged by both flavours of the benchmark. Clock and
// reset are generated by the cocotb testbench in ../cocotb/urandom.py, which
// also runs the iteration loop, so the two flavours share an identical harness.
//
// Only the randomization itself differs, and it is the sole thing inside the
// `ifdef below. When BENCH_SV_RANDOMIZE is defined the values are drawn here,
// by the simulator's random number generator. When it is not, the identical
// values are drawn from Python by random.randint instead.
//
// No constraint solver is involved on either side - this is the raw cost of
// producing a random number.

`timescale 1ns/1ps

module urandom_bench (
    input logic clk,
    input logic rst_n
);

    // Common to both flavours - lets the testbench confirm that both ran for
    // the same number of clock cycles.
    int unsigned cycles = 0;

    always @(posedge clk) begin
        if (!rst_n) begin
            cycles <= 0;
        end
        else begin
            cycles <= cycles + 1;
        end
    end

`ifdef BENCH_SV_RANDOMIZE
    // -----------------------------------------------------------------------
    // Randomization under test - SystemVerilog $urandom / $urandom_range.
    // -----------------------------------------------------------------------

    bit [31:0]       a;
    bit [31:0]       b;
    bit [31:0]       c;

    bit              enable   = 1'b1;
    int unsigned     burst    = 1;
    longint unsigned checksum = 0;
    int unsigned     count    = 0;

    initial begin
        // Cleared for the baseline run, which measures the harness on its own.
        void'($value$plusargs("randomize=%d", enable));
        void'($value$plusargs("burst=%d", burst));
    end

    always @(posedge clk) begin
        if (rst_n && enable) begin
            repeat (burst) begin
                // The full 32 bit range.
                a = $urandom();

                // A bounded range, inclusive of both ends.
                b = $urandom_range(100, 10);

                // A range from zero, inclusive.
                c = $urandom_range(255);

                if (!(b >= 32'd10 && b <= 32'd100)) begin
                    $fatal(1, "b out of range : b=%0d", b);
                end
                if (!(c <= 32'd255)) begin
                    $fatal(1, "c out of range : c=%0d", c);
                end

                checksum += 64'(a) + 64'(b) + 64'(c);
                count    += 1;
            end
        end
    end

    final begin
        $display("BENCH_RESULT flavour=sv iterations=%0d checksum=%0d", count, checksum);
    end
`endif

endmodule : urandom_bench
